// rateLimiter.js — quick-and-dirty, written under deadline. Two problems:
//   (1) It reads the wall clock directly (Date.now), so it cannot be unit-tested
//       deterministically — every test would have to sleep in real time.
//   (2) The refill logic is wrong: once a full second elapses it SLAMS the bucket
//       back to full capacity instead of adding the tokens that accrued, so a
//       caller can burst far more than the intended sustained rate.
let tokens = 5;
let lastRefill = Date.now();

function allow() {
  const now = Date.now();
  if (now - lastRefill > 1000) {
    tokens = 5;            // BUG: reset-to-full instead of incremental refill
    lastRefill = now;
  }
  if (tokens > 0) {
    tokens -= 1;
    return true;
  }
  return false;
}

module.exports = { allow };

// rateLimiter.js — refactored into a testable, injectable token bucket.
//
// The clock is injected (`now`) so behaviour is deterministic under test, and
// refill is incremental: tokens accrue at `refillPerSec` and are capped at
// `capacity`. `allow()` is preserved as a thin wrapper over a module-level
// default bucket so existing callers keep working.

class TokenBucket {
  /**
   * @param {object}   opts
   * @param {number}   opts.capacity      max tokens the bucket can hold
   * @param {number}   opts.refillPerSec  tokens added per second
   * @param {() => number} [opts.now]     clock in ms (injectable for tests)
   */
  constructor({ capacity, refillPerSec, now = () => Date.now() }) {
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
    this.now = now;
    this.tokens = capacity;
    this.last = now();
  }

  _refill() {
    const t = this.now();
    const elapsedSec = (t - this.last) / 1000;
    if (elapsedSec > 0) {
      // Incremental accrual, capped at capacity — NOT a reset-to-full.
      this.tokens = Math.min(this.capacity, this.tokens + elapsedSec * this.refillPerSec);
      this.last = t;
    }
  }

  tryRemove(n = 1) {
    this._refill();
    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }
}

const _default = new TokenBucket({ capacity: 5, refillPerSec: 5 });
function allow() {
  return _default.tryRemove(1);
}

module.exports = { TokenBucket, allow };
